/**
 * Types for the privacy classification in `privacy.ts` (spec §4.3), kept apart so the generator and
 * the postprocess script can import them without loading the whole classification.
 */

export type PiiKind = "name" | "email" | "handle" | "grade" | "free_text" | "none";

export const PII_KINDS: readonly PiiKind[] = ["name", "email", "handle", "grade", "free_text", "none"];

/**
 * Marks a value as one row (an object) or several rows (an array of objects) of a public table or
 * view; its keys are classified through that relation's `COLUMNS` entries. Used for SETOF RPCs and
 * for Json results that embed whole rows (e.g. `to_jsonb(p.*)`).
 */
export type TableRef = { readonly $table: string };

/**
 * JSONPath (subset: `$`, `.key`, `[*]`) to kind. The most specific path that covers a value decides
 * its kind, and a path to an object or array covers everything beneath it. `none` must be explicit:
 * a value no path covers is reported as unclassified, never treated as `none`.
 */
export type JsonPathMap = Readonly<Record<string, PiiKind | TableRef>>;

/**
 * An RPC's result: a kind for scalar returns and arrays of scalars, a `TableRef` for rows of a
 * table (SETOF or a single row), or a JSONPath map for Json and `RETURNS TABLE(...)` results.
 */
export type RpcClassification = PiiKind | TableRef | JsonPathMap;

export function isTableRef(v: unknown): v is TableRef {
  return typeof v === "object" && v !== null && typeof (v as { $table?: unknown }).$table === "string";
}

export function isPiiKind(v: unknown): v is PiiKind {
  return typeof v === "string" && (PII_KINDS as readonly string[]).includes(v);
}

/** One path segment: an object key, or `*` for every array element. */
export type JsonPathSegment = { key: string } | { any: true };

const SEGMENT = /\.([^.[\]]+)|\[\*\]/y;

/** Parses the JSONPath subset. Throws on anything outside `$`, `.key`, `[*]`. */
export function parseJsonPath(path: string): JsonPathSegment[] {
  if (!path.startsWith("$")) throw new Error(`JSONPath must start with $: ${path}`);
  const segments: JsonPathSegment[] = [];
  SEGMENT.lastIndex = 1;
  while (SEGMENT.lastIndex < path.length) {
    const start = SEGMENT.lastIndex;
    const m = SEGMENT.exec(path);
    if (!m) throw new Error(`unsupported JSONPath syntax at offset ${start}: ${path}`);
    segments.push(m[1] !== undefined ? { key: m[1] } : { any: true });
  }
  return segments;
}

/** Canonical text of a concrete path, with array indexes written as `[*]`, for lookups in a JsonPathMap. */
export function formatJsonPath(segments: readonly JsonPathSegment[]): string {
  return "$" + segments.map((s) => ("key" in s ? `.${s.key}` : "[*]")).join("");
}

/** Shape of `generated/relationships.json`: each public table and view, with its foreign keys. */
export type RelationshipsJson = Record<
  string,
  { kind: "table" | "view"; fks: { name: string; columns: string[]; ref: string }[] }
>;

/** Shape of `generated/edgeFunctionWrappers.json`: edge function slug to the wrappers that invoke it. */
export type EdgeWrappersJson = Record<string, string[]>;
/**
 * Maps a Supabase response to the privacy kinds of its values (bug reporter spec, package 2).
 *
 * - PostgREST (`/rest/v1/<relation>`): response keys map to `relation.column` through the URL's
 *   `select=`, following aliases (`mentor:profiles(...)`), FK hints (`profiles!fk_name(...)`,
 *   `!inner`), and nested embeds; `*` maps every other key to a column of the current relation.
 * - RPC (`/rest/v1/rpc/<fn>`): through `RPCS`; a `{ $table }` result is walked as rows, honoring
 *   `select=` when the call has one.
 * - Edge functions (`/functions/v1/<slug>`): through `EDGE_FUNCTIONS`, the union of every wrapper in
 *   `lib/edgeFunctions.ts` that invokes the slug.
 *
 * Only non-`none` values come out. Keys and paths with no classification are reported in
 * `unclassified` rather than guessed.
 */
import { COLUMNS, EDGE_FUNCTIONS, RPCS } from "./privacy";
import edgeWrappers from "./generated/edgeFunctionWrappers.json";
import relationshipsJson from "./generated/relationships.json";
import {
  formatJsonPath,
  isPiiKind,
  isTableRef,
  type EdgeWrappersJson,
  type JsonPathMap,
  type JsonPathSegment,
  type PiiKind,
  type RelationshipsJson,
  type TableRef
} from "./privacyTypes";

export type TaintKind = Exclude<PiiKind, "none">;

/** One classified value. `source` names where the kind came from ("profiles.name", "rpc:fn $.x"). */
export type ClassifiedValue = { value: string; kind: TaintKind; source: string };

export type ClassifyResult = {
  /** False when the URL is not a PostgREST, RPC, or edge-function URL. */
  handled: boolean;
  values: ClassifiedValue[];
  /** Keys ("table.column") or paths ("rpc:fn $.x") that have no classification. */
  unclassified: string[];
};

export type SelectItem = {
  /** Response key: the alias, else the column or relation name (or the last `->` segment). */
  key: string;
  /** Column or relation name, without hints or JSON path. */
  name: string;
  hints: string[];
  /** Present for embeds. */
  children?: SelectTree;
};

export type SelectTree = { star: boolean; items: SelectItem[] };

const RELATIONS = relationshipsJson as RelationshipsJson;
const WRAPPERS_BY_SLUG = edgeWrappers as EdgeWrappersJson;

// --- select= parsing ----------------------------------------------------------------------------

function splitTopLevel(s: string): string[] {
  const parts: string[] = [];
  let depth = 0;
  let quoted = false;
  let start = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === '"') quoted = !quoted;
    else if (quoted) continue;
    else if (c === "(") depth++;
    else if (c === ")") depth--;
    else if (c === "," && depth === 0) {
      parts.push(s.slice(start, i));
      start = i + 1;
    }
  }
  parts.push(s.slice(start));
  return parts.map((p) => p.trim()).filter((p) => p.length > 0);
}

const unquote = (s: string) => s.replace(/^"(.*)"$/, "$1");

/** Parses a PostgREST `select` value, e.g. `*,mentor:profiles!fk(name),users!inner(email)`. */
export function parseSelect(select: string): SelectTree {
  const tree: SelectTree = { star: false, items: [] };
  for (const part of splitTopLevel(select.replace(/\s+(?=(?:[^"]*"[^"]*")*[^"]*$)/g, ""))) {
    if (part === "*") {
      tree.star = true;
      continue;
    }
    const open = part.indexOf("(");
    const head = open >= 0 ? part.slice(0, open) : part;
    const inner = open >= 0 ? part.slice(open + 1, part.lastIndexOf(")")) : undefined;
    // [alias:]name[!hint...][->json->>path][::cast]
    const aliased = head.match(/^([^:!]+):(?!:)(.*)$/);
    const alias = aliased ? unquote(aliased[1]) : undefined;
    const rest = (aliased ? aliased[2] : head).replace(/::[\w\s[\]]+$/, "");
    const [target, ...hints] = rest.split("!");
    const jsonPath = target.split(/->>?/);
    const name = unquote(jsonPath[0]);
    const key = alias ?? (jsonPath.length > 1 ? unquote(jsonPath[jsonPath.length - 1]) : name);
    const item: SelectItem = { key, name, hints: hints.map(unquote) };
    if (inner !== undefined) item.children = parseSelect(inner);
    tree.items.push(item);
  }
  return tree;
}

/**
 * The relation an embed reads from. An embed names a relation directly (hints only disambiguate
 * which FK); otherwise it names an FK constraint or FK column of the parent, resolved through the
 * generated relationships.
 */
export function resolveEmbed(parent: string, item: SelectItem): string | null {
  if (RELATIONS[item.name]) return item.name;
  const fks = RELATIONS[parent]?.fks ?? [];
  for (const ref of [item.name, ...item.hints]) {
    const matches = fks.filter((fk) => fk.name === ref || (fk.columns.length === 1 && fk.columns[0] === ref));
    // A table FK is also listed against every view built on the referenced table; prefer the table.
    const match = matches.find((fk) => RELATIONS[fk.ref]?.kind === "table") ?? matches[0];
    if (match) return match.ref;
  }
  return null;
}

// --- walking ------------------------------------------------------------------------------------

class Collector {
  values: ClassifiedValue[] = [];
  private missing = new Set<string>();
  unclassified(key: string) {
    this.missing.add(key);
  }
  get unclassifiedKeys() {
    return [...this.missing];
  }
  /** Emits every string (and, for grades and handles, number) at or beneath `v`. */
  leaves(v: unknown, kind: PiiKind, source: string) {
    if (kind === "none" || v === null || v === undefined) return;
    if (typeof v === "string") {
      if (v.length > 0) this.values.push({ value: v, kind, source });
    } else if (typeof v === "number") {
      if (kind === "grade" || kind === "handle") this.values.push({ value: String(v), kind, source });
    } else if (Array.isArray(v)) {
      for (const x of v) this.leaves(x, kind, source);
    } else if (typeof v === "object") {
      for (const x of Object.values(v as Record<string, unknown>)) this.leaves(x, kind, source);
    }
  }
}

function walkRows(out: Collector, relation: string, rows: unknown, select: SelectTree | null) {
  if (Array.isArray(rows)) {
    for (const r of rows) walkRows(out, relation, r, select);
    return;
  }
  if (rows === null || typeof rows !== "object") return;
  const star = select === null || select.star;
  const byKey = new Map((select?.items ?? []).map((i) => [i.key, i]));
  for (const [key, value] of Object.entries(rows as Record<string, unknown>)) {
    const item = byKey.get(key);
    if (item?.children) {
      const target = resolveEmbed(relation, item);
      if (!target) out.unclassified(`${relation}.${key} (embed)`);
      else walkRows(out, target, value, item.children);
      continue;
    }
    const column = item ? item.name : star ? key : undefined;
    if (column === "count" && typeof value === "number") continue;
    const colKey = `${relation}.${column ?? key}`;
    const kind = column !== undefined ? COLUMNS[colKey] : undefined;
    if (kind === undefined) {
      if (value !== null) out.unclassified(colKey);
      continue;
    }
    out.leaves(value, kind, colKey);
  }
}

/** Walks `body` against a JSONPath map; the most specific matching path decides each value's kind. */
function walkJsonPathMap(
  out: Collector,
  map: JsonPathMap,
  body: unknown,
  source: string,
  select: SelectTree | null = null
) {
  const visit = (node: unknown, path: JsonPathSegment[], inherited: PiiKind | undefined) => {
    const p = formatJsonPath(path);
    const here: PiiKind | TableRef | undefined = map[p];
    if (isTableRef(here)) {
      walkRows(out, here.$table, node, select);
      return;
    }
    const kind = isPiiKind(here) ? here : inherited;
    if (node === null || node === undefined) return;
    if (Array.isArray(node)) {
      for (const x of node) visit(x, [...path, { any: true }], kind);
    } else if (typeof node === "object") {
      for (const [k, v] of Object.entries(node as Record<string, unknown>)) visit(v, [...path, { key: k }], kind);
    } else if (kind === undefined) {
      out.unclassified(`${source} ${p}`);
    } else {
      out.leaves(node, kind, `${source} ${p}`);
    }
  };
  visit(body, [], undefined);
}

function edgeFunctionMap(slug: string): JsonPathMap | undefined {
  const wrappers = WRAPPERS_BY_SLUG[slug];
  if (!wrappers) return undefined;
  const merged: Record<string, PiiKind | TableRef> = {};
  for (const w of wrappers) {
    for (const [p, v] of Object.entries(EDGE_FUNCTIONS[w] ?? {})) {
      // Wrappers sharing a slug may classify one path differently; the first PII kind wins over none.
      if (merged[p] === undefined || merged[p] === "none") merged[p] = v;
    }
  }
  return merged;
}

/**
 * Classifies a Supabase response body. `url` may be absolute or relative; `method` is accepted for
 * the ingest wrapper's convenience (every method that returns a body is classified the same way).
 */
export function classifyResponse(url: string, method: string, body: unknown): ClassifyResult {
  const out = new Collector();
  let parsed: URL;
  try {
    parsed = new URL(url, "http://localhost");
  } catch {
    return { handled: false, values: [], unclassified: [] };
  }
  const selectParam = parsed.searchParams.get("select");
  const select = selectParam ? parseSelect(selectParam) : null;
  const path = parsed.pathname;
  let m: RegExpMatchArray | null;
  if (method.toUpperCase() === "HEAD" || method.toUpperCase() === "OPTIONS") {
    return { handled: false, values: [], unclassified: [] };
  } else if ((m = path.match(/\/rest\/v1\/rpc\/([^/]+)\/?$/))) {
    const fn = decodeURIComponent(m[1]);
    const c = RPCS[fn];
    if (c === undefined) out.unclassified(`rpc:${fn}`);
    else if (isTableRef(c)) walkRows(out, c.$table, body, select);
    else if (isPiiKind(c)) out.leaves(body, c, `rpc:${fn}`);
    else walkJsonPathMap(out, c, body, `rpc:${fn}`, select);
  } else if ((m = path.match(/\/rest\/v1\/([^/]+)\/?$/))) {
    const relation = decodeURIComponent(m[1]);
    if (!RELATIONS[relation]) out.unclassified(relation);
    else walkRows(out, relation, body, select);
  } else if ((m = path.match(/\/functions\/v1\/([^/]+)/))) {
    const slug = decodeURIComponent(m[1]);
    const map = edgeFunctionMap(slug);
    if (!map) out.unclassified(`edge:${slug}`);
    else walkJsonPathMap(out, map, body, `edge:${slug}`);
  } else {
    return { handled: false, values: [], unclassified: [] };
  }
  return { handled: true, values: out.values, unclassified: out.unclassifiedKeys };
}

/** Classifies rows of a known relation (TableController `initialData`, realtime `postgres_changes`). */
export function classifyRows(relation: string, rows: unknown): Omit<ClassifyResult, "handled"> {
  const out = new Collector();
  walkRows(out, relation, rows, null);
  return { values: out.values, unclassified: out.unclassifiedKeys };
}
/**
 * Turns classified values into the strings the taint set matches (bug reporter spec, package 2).
 *
 * Every pattern is case- and whitespace-normalized with `normalizeForMatch`, so the matcher must
 * normalize the text it scans the same way. Patterns under `MIN_MATCH_LENGTH` characters, initials,
 * and grades are never produced: those are blocked structurally (`<ReportBlock>`, package 3) instead,
 * because matching "87" or "J." would redact unrelated text without protecting anyone.
 */
import type { PiiKind } from "./privacyTypes";

export const MIN_MATCH_LENGTH = 3;

/** Lower case, NFKC, runs of whitespace collapsed to one space, trimmed. */
export function normalizeForMatch(text: string): string {
  return text.normalize("NFKC").toLowerCase().replace(/\s+/g, " ").trim();
}

/** "J", "JD", "J.", "J.D.", "J. D.", "D., J." (up to three letters when each has a dot). */
function isInitials(token: string): boolean {
  const t = token.replace(/[\s,]/g, "");
  return /^(?:\p{L}\.?){1,2}$/u.test(t) || /^(?:\p{L}\.){1,3}$/u.test(t);
}

function keep(out: Set<string>, candidate: string) {
  const n = normalizeForMatch(candidate);
  if (n.length < MIN_MATCH_LENGTH || isInitials(n)) return;
  out.add(n);
}

/**
 * Variants of a person's name: the full name, its first and last tokens, "Last, First", and
 * "First Last" when the input is already in sortable "Last, First" form.
 */
export function nameVariants(name: string): string[] {
  const out = new Set<string>();
  const trimmed = name.replace(/\s+/g, " ").trim();
  if (!trimmed) return [];
  keep(out, trimmed);
  const sortable = trimmed.match(/^([^,]+),\s*(.+)$/);
  const ordered = sortable ? `${sortable[2]} ${sortable[1]}` : trimmed;
  const tokens = ordered.split(" ").filter((t) => t.length > 0);
  if (tokens.length > 1) {
    const first = tokens[0];
    const last = tokens[tokens.length - 1];
    keep(out, first);
    keep(out, last);
    keep(out, `${first} ${last}`);
    keep(out, `${last}, ${first}`);
    keep(out, ordered);
  }
  return [...out];
}

/** The staff-facing form rendered by `components/ui/person-name.tsx`: "Pseudonym (Real Name)". */
export function personNameDisplay(name: string, realName: string): string {
  return `${name} (${realName})`;
}

/** Variants of both names plus the `name (real_name)` display form. */
export function personNameVariants(name: string, realName?: string | null): string[] {
  const out = new Set(nameVariants(name));
  if (realName) {
    for (const v of nameVariants(realName)) out.add(v);
    keep(out, personNameDisplay(name, realName));
  }
  return [...out];
}

/**
 * The normalized strings to add to the taint set for one classified value. Empty for `grade` and
 * `none`, which are never string-matched.
 */
export function matchPatterns(value: string, kind: PiiKind): string[] {
  switch (kind) {
    case "none":
    case "grade":
      return [];
    case "name":
      return nameVariants(value);
    case "email": {
      const out = new Set<string>();
      keep(out, value);
      const at = value.lastIndexOf("@");
      if (at > 0) keep(out, value.slice(0, at));
      return [...out];
    }
    case "handle":
    case "free_text": {
      const out = new Set<string>();
      keep(out, value);
      return [...out];
    }
  }
}
# Reviewing the privacy classification (HU6)

`privacy.ts` is a generated draft. It assigns a privacy kind to every value the browser can receive from Supabase, and the bug reporter redacts values of every kind except `none` from a recording before upload. Nothing in the draft is approved until a human reviews it (HU6 in the bug reporter spec). This guide covers how the draft was made, which entries are guesses, and where to look first.

## How the draft was made

`scripts/bugReport/generatePrivacyDraft.ts` writes `privacy.ts` from four sources, in this order of precedence:

1. **Hand overrides** (`scripts/bugReport/privacyOverrides.ts`), for columns the rules get wrong, and every edge-function wrapper.
2. **RPC return shapes read from SQL** (`scripts/bugReport/rpcReturnReview.json`). This covers the 58 functions whose SQL return type is Json, text, or a record. Each entry records the shape, whether the browser calls the function, and a reason when the reading was a guess.
3. **Column-name rules** (`scripts/bugReport/columnHeuristics.ts`). These are the patterns from the spec (`name`, `sortable_name`, `email`, `*_username`, `score*`, `body`, `message`, and more) plus the columns listed in `docs/operations/data-retention.md` §"PII / grades". Foreign-key and id columns are `none`. When a rule is unsure it picks a PII kind.
4. **Generated return types** for the remaining RPCs. Boolean, number, and void returns are `none`. `SETOF` a table becomes `{ $table }`, and `RETURNS TABLE(...)` columns go through the column rules.

Entries the draft was unsure about carry a `// UNCERTAIN: <reason>` comment. Entries added after a schema change carry `// DRAFT`. Delete the comment once you have decided.

| Section        | Entries | Non-`none` | `// UNCERTAIN` |
| -------------- | ------- | ---------- | -------------- |
| COLUMNS        | 1793    | 213        | 64             |
| RPCS           | 326     | 50         | 23             |
| EDGE_FUNCTIONS | 54      | 45\*       | 5              |

\* Every wrapper that invokes an edge function maps `$.error` to `free_text`, because the error bodies from `wrapRequestHandler` often quote usernames, emails, or repository names; 30 of them also have PII beyond the error body. The 9 wrappers that only call RPCs map `$` to `none`, and their results are classified under RPCS.

Columns by kind: 1580 `none`, 102 `free_text`, 46 `grade`, 34 `handle`, 24 `name`, 7 `email`.

## What the kinds mean here

- `name`: a person's name, including generated pseudonyms (the public `profiles.name`) and git commit author names. The taint set also matches first and last tokens and "Last, First".
- `email`: addresses. The taint set also matches the local part.
- `handle`: anything that identifies a person outside Pawtograder: GitHub and Discord usernames and ids, SIS, Canvas, and LTI ids, IP addresses, avatar URLs, and **student repository names**, which embed the GitHub username.
- `grade`: scores, points awarded, score overrides, karma, and **extension hours and late tokens**. Grades are never string-matched; package 3 blocks the components that render them.
- `free_text`: anything a user typed, plus error and sync messages from upstream services, plus Json blobs whose shape is unknown.
- `none`: ids, timestamps, enums, counts, and course content that staff write for the whole class.

## Decisions to confirm

These choices affect many entries. The draft makes a call on each, and a reviewer should confirm or reverse it.

1. **Course content is `none`.** This covers assignment titles and descriptions, rubric names and text, class, section, and help queue names, survey definitions, flashcard prompts, and poll questions. The draft assumes staff-authored text for the whole class names no student. If that is wrong, these become `free_text`, and package 3 would block every component that renders them.
2. **Unknown Json blobs are `free_text`.** Examples are `audit.old`/`new`, GitHub webhook payloads, DLQ envelopes, and `repository_check_runs.status`. `free_text` taints every string inside the blob, including enum values such as `"open"` or `"submitted"`. Those strings would then be redacted wherever they appear in unmasked text. The ingest phase may need to skip short or enum-like values from these sources; that is a product decision.
3. **Error and sync messages are `free_text`.** GitHub, Discord, and Canvas errors often quote a username. Most of these columns are readable only by admins, so the cost is small.
4. **Extensions and late tokens are `grade`**, because they can reveal an accommodation.
5. **Secrets are `free_text`**, although they are not PII. These are `get_assessment_export_pepper`, the MCP token returned on creation, and `lti_tool_keys.private_key_pem_encrypted`. There is no `secret` kind, and `free_text` keeps them out of a replay.

## Rows to look at first

- **Guesses about names on unfamiliar relations.** `calendar_events.title`, `description`, and `location` are `free_text` because staff calendars often name a TA. `lab_sections.name` and `class_sections.name` are `none`, but hand-made section names can name their leader. Student-chosen names are `free_text`: `assignment_groups.name`, `tags.name`, `submission_files.name`, and branch names (`head_branch`).
- **`get_gradebook_records_for_all_students_array`.** Each entry is a positional array that mixes scores with the free-text `score_override_note` at index 9. The JSONPath subset cannot address an index, so the whole array is `grade`. The note is therefore protected only by blocking, never by matching.
- **`custom_access_token_hook`.** The SQL passes the auth event through unchanged, so its classification describes the usual Supabase claims rather than anything read from code.
- **`bulk_csv_import_enrollment.$.errors[*].identifier`.** It holds an email or a SIS id, depending on the import mode, and is classified as `email`.
- **`getPrBaseFiles` and `pr_base_tree_cache.files`** are `none` on the assumption that the upstream base is the instructor's handout code.
- **`repositoriesForClass` and `repositoryListCommits`.** Only the name, login, email, and avatar fields of the Octokit objects are classified. URL fields embed those values and rely on substring matching.

## Known gaps

- `app/course/[course_id]/assignments/[assignment_id]/submissions/[submissions_id]/files/page.tsx` calls the `submission-serve-artifact` edge function directly, not through a wrapper in `lib/edgeFunctions.ts`. The select parser reports its response as unclassified.
- JSONPath cannot express keys of dynamic objects, such as objects keyed by student id. Such values are classified through their parent path.

## Keeping it current

`npm run client` and `npm run client-local` fail when the schema gains a column, view field, or RPC that `privacy.ts` lacks, or when `lib/edgeFunctions.ts` gains a wrapper; the unit test `tests/unit/bugReport/privacyExhaustive.test.ts` fails in CI for the same reasons. To fix either, run `npx tsx scripts/bugReport/generatePrivacyDraft.ts`. It keeps every existing entry, including hand edits, adds `// DRAFT` entries for new keys, and drops entries for keys that no longer exist. Review the new entries, then rerun `npm run client-local`. `--fresh` rebuilds every entry from the sources above and discards hand edits.

