// Helper function to enroll existing users in a class
export async function enrollExistingUserInClass(
  user: TestingUser,
  class_id: number,
  rateLimitManager: RateLimitManager,
  /** Demo-mode personas use non-prefixed emails (e.g. ripley@ripley.cloud);
   * pass the role explicitly in that case. */
  explicitRole?: "student" | "instructor" | "grader"
): Promise<TestingUser> {
  // Recycled demo users historically inherited an email as their profile name.
  // Always assign a fresh synthetic human name so the UI shows real-looking names,
  // not email addresses, and a separate pseudonym for the public (anonymous) profile.
  const privateName = faker.person.fullName();
  const publicName = `${faker.word.adjective()}-${faker.animal.type()}-${faker.number.int({ min: 100, max: 999 })}`;

  const { data: privateProfile, error: privateProfileError } = await rateLimitManager.trackAndLimit("profiles", () =>
    supabase
      .from("profiles")
      .insert({
        name: privateName,
        class_id: class_id,
        is_private_profile: true
      })
      .select("id")
  );

  if (privateProfileError) {
    throw new Error(`Failed to create private profile: ${privateProfileError.message}`);
  }

  // Create new public profile
  const { data: publicProfile, error: publicProfileError } = await rateLimitManager.trackAndLimit("profiles", () =>
    supabase
      .from("profiles")
      .insert({
        name: publicName,
        class_id: class_id,
        is_private_profile: false
      })
      .select("id")
  );

  if (publicProfileError) {
    throw new Error(`Failed to create public profile: ${publicProfileError.message}`);
  }

  // Determine role: caller-provided wins, otherwise infer from email prefix.
  const role: "student" | "instructor" | "grader" =
    explicitRole ??
    (user.email.startsWith("instructor-") ? "instructor" : user.email.startsWith("grader-") ? "grader" : "student");

  // Insert user role with new profiles
  const { error: userRoleError } = await rateLimitManager.trackAndLimit("user_roles", () =>
    supabase
      .from("user_roles")
      .insert({
        user_id: user.user_id,
        role: role,
        class_id: class_id,
        private_profile_id: privateProfile[0].id,
        public_profile_id: publicProfile[0].id
      })
      .select("user_id")
  );

  if (userRoleError) {
    throw new Error(`Failed to create user role: ${userRoleError.message}`);
  }

  // Return updated user with new profile IDs, names, and class_id
  return {
    ...user,
    class_id,
    private_profile_name: privateName,
    public_profile_name: publicName,
    private_profile_id: privateProfile[0].id,
    public_profile_id: publicProfile[0].id
  };
}

